import path from "node:path";
import { fileURLToPath } from "node:url";
import { DEFAULT_EXECUTION, resolveWorkspacePath, selectPageAggregate, selectSingleClaimExecution } from "./single-claim-contract.mjs";

const here = path.dirname(fileURLToPath(import.meta.url));
const workspace = path.resolve(here, "../..");
const sourceDir = path.join(workspace, "ccd-109/run");
const outDir = process.env.CCD143_OUT_DIR ? resolveWorkspacePath(workspace, process.env.CCD143_OUT_DIR) : path.join(workspace, "ccd-143/run");
const expressionDir = path.join(outDir, "expressions");
const plan = JSON.parse(await readFile(path.join(sourceDir, "plan.json"), "utf8"));
const originalInput = JSON.parse(await readFile(path.join(sourceDir, "target-expression-input.json"), "utf8"));
const pageFiles = (await readdir(path.join(sourceDir, "pages"))).filter(name => name.endsWith(".json")).sort();
const sourcePages = await Promise.all(pageFiles.map(async name => JSON.parse(await readFile(path.join(sourceDir, "pages", name), "utf8"))));
const sha256 = value => createHash("sha256").update(value).digest("hex");
const runId = process.env.PAPERCLIP_RUN_ID || `offline-${Date.now()}`;
const runShortId = runId.replace(/[^a-z0-9]/giu, "").slice(0, 8).toLowerCase() || "ccd14300";
const producerPath = "ccd-143/scripts/build-lifecycle-expressions.mjs";
const producerSha256 = sha256(await readFile(new URL(import.meta.url)));
const producerRef = { kind: "workspace-file", path: producerPath, sha256: producerSha256 };
const issue = "CCD-143";
