const executionConfig = executionConfigPath ? JSON.parse(await readFile(executionConfigPath, "utf8")) : null;
const requestedSourcePage = executionConfig ? sourcePages.find(page => page.page.rowNumber === executionConfig.rowNumber) : null;
const requestedTargetPage = executionConfig ? originalInput.pages.find(page => page.rowNumber === executionConfig.rowNumber) : null;
const claim = executionConfig ? JSON.parse(await readFile(resolveWorkspacePath(workspace, executionConfig.claimLocator), "utf8")) : null;
