const markerPath = `/SiteAssets/${markerName}`;

const conflictSitePaths = new Set(
  String(process.env.CCD143_SITE_CONFLICT_PATHS || "")
    .split(",")
    .map(value => value.trim())
    .filter(Boolean)
);
const conflictSuffixOrdinal = Math.max(1, Number.parseInt(process.env.CCD143_CONFLICT_SUFFIX_ORDINAL || "1", 10) || 1);
const conflictSuffix = `-ccd35-${runShortId}${conflictSuffixOrdinal > 1 ? `-${conflictSuffixOrdinal}` : ""}`;
const sitePathMappings = scopedInput.sites.map(site => {
  const sourceTargetPath = site.targetPath;
  const targetPath = conflictSitePaths.has(sourceTargetPath)
    ? `${sourceTargetPath}${conflictSuffix}`
    : sourceTargetPath;
  return { sourceTargetPath, targetPath, reason: targetPath === sourceTargetPath ? "SOURCE_RELATIVE_EXACT" : "TARGET_SITE_CONFLICT" };
});
const replaceTargetPrefix = value => {
  if (!value) return value;
  const mapping = [...sitePathMappings]
    .sort((left, right) => right.sourceTargetPath.length - left.sourceTargetPath.length)
    .find(candidate => value === candidate.sourceTargetPath || value.startsWith(`${candidate.sourceTargetPath}/`));
  return mapping ? `${mapping.targetPath}${value.slice(mapping.sourceTargetPath.length)}` : value;
};
const sites = scopedInput.sites.map(site => {
  const targetPath = replaceTargetPrefix(site.targetPath);
  return {
    ...site,
    targetPath,
    targetUrl: `${targetOrigin}${targetPath}`,
    title: targetPath === site.targetPath ? site.title : path.posix.basename(targetPath)
  };
});
const webs = scopedInput.webs.map(web => ({
  ...web,
  targetPath: replaceTargetPrefix(web.targetPath),
  sitePath: replaceTargetPrefix(web.sitePath)
}));
const libraries = scopedInput.libraries.map(library => ({
  ...library,
  webPath: replaceTargetPrefix(library.webPath),
  rootPath: replaceTargetPrefix(library.rootPath)
}));

const systemConflictRows = new Set([8, 11, 23]);
