  schema: "ccd.shared-target-plan/v2",
  sourcePlanDigest,
  runId,
  targetOrigin,
  sitePathMappings,
  pageMappings: pages.map(page => ({ rowNumber: page.rowNumber, preferredPath: page.preferredPath, targetPath: page.targetPath, operationId: page.operationId }))
