    web: { attempts: 36, intervalMs: 5000, timeoutMs: 180000 },
    list: { attempts: 20, intervalMs: 750, timeoutMs: 15000 },
    cleanup: { attempts: 45, intervalMs: 1500, timeoutMs: 67500 }
